  "30 modeled days / 22 workdays (4.4 weeks)": ": 30天建模期/22个工作日（4.4周）",
  "30-DAY MODEL MONTHS": "30天模式月份",
  "4 designer hours × $18 + 2.1 owner hours × $38 = $151.80 modeled cost floor; $175 sell price is above the floor and within the $125–$250 modeled range informed by Michigan $50+ social, $75+ flyer and $147+ print-design starts.": "4位设计师小时×18美元 + 2.1位负责人小时×38美元 = 模型成本底线为151.80美元；175美元的售价高于底线，且处于由密歇根州提供的125美元至250美元之间模型价格区间，包括50美元以上的社交媒体费用、75美元以上的宣传单费用，以及147美元以上的印刷设计启动费用。",
  "4 outreach hours/week × 6 contacts/hour × 5% qualified × 4.4 weeks = 5.28/month": "每周4小时接触时间 × 每小时5次接触 × 5%合格客户 × 4.4周 = 每月5.28次接触",
  "4.5 designer hours × $18 + 2.1 owner hours × $38 + Printyco’s observed $75 batch = $235.80 floor; $325 remains within $275–$425.": "4.5名设计师小时×18美元+2.1名负责人小时×38美元+Printyco观察到的75美元批量成本=235.80美元；325美元仍位于275美元至425美元之间。",
  "4.5 designer hours × $18 + 2.1 owner hours × $38 + Royal’s observed $100 batch = $260.80 floor; $325 allows coordination risk while staying inside $275–$425.": "4.5位设计师小时×18美元 + 2.1位负责人小时×38美元 + 罗亚尔观察到的100美元批量费用 = 260.80美元的模型底线；325美元的售价可以承担协调风险，同时保持在275美元至425美元的范围内。",
  "4x6, 14pt/16pt UV, one side": "4x6英寸，14点或16点UV油墨，单面印刷",
  "4x6, 14pt/16pt UV, one side as listed": "4x6英寸，14点或16点UV油墨，单面如所列价格",
  "5 designer hours × $18 + 2.35 owner hours × $38 + 12 sq ft × modeled $6 from Royal’s listed $5–$10 = $251.30; $425 excludes installation and sits within $350–$600.": "5位设计师小时×18美元 + 2.35位负责人小时×38美元 + 12平方英尺×模型6美元的费用，按照罗亚尔列出的5美元至10美元计算 = 251.30美元；425美元的售价不包括安装费用，且处于350美元至600美元的范围内。",
  "5 designer hours × $18 + 2.35 owner hours × $38 + Printyco’s observed $95 minimum batch = $274.30 floor; $395 remains inside $350–$525.": "5位设计师小时×18美元 + 2.35位负责人小时×38美元 + 普林特科观察到的95美元最低批量费用 = 274.30美元的模型底线；395美元的售价仍然处于350美元至525美元的范围内。",
  "5.28 qualified inquiries/month × 30% accepted = 1.584 initial wins/month": "每月5.28次合格咨询 × 30%的接受率 = 每月1.584次初始成功案例",
  "7 designer hours × $18 + 2.6 owner hours × $38 = $224.80 floor; $300 equals $75 per supplied-content asset and lies in the $240–$425 modeled range informed by $50+ social and $297+ digital starts.": "7名设计师小时×18美元+2.6名负责人小时×38美元=224.80美元；提供的每项内容资产价值75美元，处于由50美元以上的社交启动费用和297美元以上的数字启动费用所确定的240美元至425美元之间。",
  "7 designer hours × $18 + 2.6 owner hours × $38 = $224.80 floor; $350 sits between published $250 template-menu work and $600 brand-upgrade work and below 7 hours at the published $84 Michigan rate.": "7位设计师小时×18美元 + 2.6位负责人小时×38美元 = 224.80美元的模型底线；350美元的售价介于公布的250美元模板菜单工作和600美元的品牌升级工作之间，而7小时的工时按照密歇根州的84美元标准计算则低于公布的费率。",
