  "A data-readiness summary and documented definitions. Checked findings, their limitations and a proposed next action. A reproducible working file or report in the agreed format.": "一份数据准备总结和文档化的定义。经过验证的发现结果及其局限性，以及拟议的下一步行动。一份可复制的工作文件或报告，采用约定的格式。",
  "A dated evidence note describing the researched segment and channel options.": "一份注明日期的证据说明，描述了研究过的细分市场和渠道选项。",
