  "A structured product-information file with documented missing fields. The agreed descriptions, image assets or sales sheets. A review log identifying approved specifications and claims.": "具有文档化的缺失字段的结构化产品信息文件。商定描述、图片资源或销售表格。包含识别已批准规格和声明的评论日志。",
