  "Continue from the saved month-end settings. Later settings, funding and project decisions from the original run are unavailable here.": "继续从保存的月末设置中操作。此处无法使用原始运行后的后续设置、资金安排和项目决策。",
  "Contract economics": "合同经济学",
  "Contracts": "合同",
  "Contribution": "边际贡献",
  "Contribution = delivered revenue − direct costs on delivered cycles. *After owner time = revenue − all incurred contract costs − recorded contract hours × current owner target. It excludes shared overhead, outreach and time on declined new quotes. Open cycles can make this interim result negative. Contract totals will not equal the whole-business result.": "贡献 = 交付收入 - 交付周期的直接成本。*扣除负责人人工时间后的收入 - 所有合同成本 - 记录的合同工时 × 当前负责人目标。不包括共享开销、推广以及拒绝的新报价所花费的时间。开放周期可能导致此中期结果为负。合同总计不会等于整体业务结果。",
  "Contribution margin": "边际贡献率",
  "Contribution per accepted project · {0} managed / {1} files only.": "每个接受项目的贡献 · {0} 管理/仅{1}个文件。",
  "Contribution · high to low": "贡献 · 从高到低",
  "Controls": "控制",
  "Conversion": "转化率",
  "Conversion excludes undecided quotes and returning orders. Returning share measures orders, not customer retention. Late deliveries and overdue payments are separate.": "转化率不包括未决定的报价和退货订单。退货指标衡量的是订单数量，而非客户留存率。延迟交付和逾期付款是分开统计的。",
  "Conversion is the share of new-business quotes that accept. Confirmed repeats and paid-cycle renewals bypass new-sales conversion. A deposit is received on acceptance; revenue is recognized on delivery.": "转化率是指新业务报价中接受的比例。已确认的重复订单和付费周期续订则绕过新销售转化率的计算。在报价确认时收取定金，在交付时确认收入。",
  "Conversion rate": "转化率",
  "Coordinated counter/poster run plus four digital companions": "协调的计数器/海报模拟，外加四张数字辅助图",
  "Coordination work does not silently make the studio the inventory owner or purchaser.": "协调工作不会让工作室成为库存负责人或购买者。",
  "Copied catalog details are starting assumptions. Check the scope and source dates before using them for your studio.": "复制的目录详情是初始假设。在使用它们之前，请检查范围和使用日期。",
  "Copies kept when an older save was updated or an invalid draft was recovered. Download an original, or restore its valid unfinished setup inputs without replacing the active run.": "当较旧的保存文件被更新或无效的草稿被恢复时，会保留副本。下载原始文件，或恢复有效的未完成设置输入，而不需要替换正在运行的流程。",
  "Copies the current working scope, price and estimates into a preserved snapshot. This does not send a quote or record a payment.": "将当前的工作范围、价格和估算值复制到存档快照中。此操作不会发送报价或记录付款。",
