  "Direct costs cover delivered design labor and print/shipping. Shared overhead and owner-time value are excluded from service contribution.": "直接成本涵盖交付的设计劳动及打印/运输费用。共享的间接费用和负责人人工价值不计入服务贡献中。",
  "Direct costs exclude overhead and your time. Quote effort locks at intake. Delivery effort and commercial terms lock at acceptance.": "直接成本不包括间接费用以及您的工作时间。报价在接收时锁定。交付工作和商业条款在接受时锁定。",
  "Direct costs from days {0}–{1} · Original {2} · Changed {3}": "从日{0}到{1}的直接成本 · 原值{2} · 调整后{3}",
  "Direct costs include design labor and print/shipping. Margin = result ÷ delivered revenue; shown as — when revenue is zero. Owner time is valued at the current {0}/h across the entire run.": "直接成本包括设计人工费、印刷费和运费。利润率等于利润除以已交付项目的收入，收入为零时显示为“—”。整段模拟中，负责人的工时均按当前每小时 {0} 计价。",
