  "Expected unit figures weight the available quote routes by the modeled customer-choice share. They are assumptions, not realized sales, guaranteed revenue, subscriptions, or prepaid annual commitments.": "预期单位数值根据模型化的客户选择比例对可用报价路线进行加权。这些是假设，而非实际销售、保证收入、订阅或预付年度承诺。",
