  "Explore a bounded diagnostic before assuming a recurring reporting service.": "在假设一个重复报告服务之前，先探索一个有界诊断。",
  "Explore a menu refresh, table tents and a monthly promotion. The studio’s prices, time and demand are example estimates.": "从菜单改版、桌牌和每月促销三项服务入手。示例中的价格、工时和客户需求均为估算值。",
