  "Published design and print prices are frozen comparables. Package prices, work estimates, demand, customer printing preferences and disruption rates are modeled assumptions with documented derivations, not measured results for your business. Named staff, supplier comparisons, borrowing and native Windows/Mac installers remain future work. Backups include model and workload identities.": "发布的设计和印刷价格具有固定可比性。包装价格、工作量估算、需求、客户印刷偏好以及中断率都是基于有文档依据的假设进行建模的，并非针对您企业的实际测量结果。命名员工、供应商比较、借用资源以及原生Windows/Mac安装程序仍属于未来的工作。备份包括模型和工作量的标识。",
  "Published prices are comparables for the stated scope. Your customer price, work estimate and supplier allowance remain editable assumptions.": "公布的定价适用于所述范围。您的客户价格、工作量估算和供应商费用仍然是可编辑的假设。",
