  "Scope and exclusions": "服务范围与不包含的事项",
  "Scope owner agrees the batch and required fields → specialist normalizes source information → content work uses verified details → client or qualified reviewer resolves factual questions → approved outputs are prepared for the agreed destination.": "范围负责人同意批次和所需字段→专家规范源信息→内容制作使用已验证的详细信息→客户或合格的评论员解决事实问题→已批准的输出为约定的目标格式准备。",
  "Scope owner and buyer agree requirements → coordinator obtains comparable information → reviewer checks specifications and exclusions → an explicitly authorized sample is assessed → buyer decides whether to proceed.": "范围负责人与买家确认需求后，协调员获取可比较的信息，审核员检查规格及排除项，经过明确授权的样品进行评估，最终由买家决定是否继续推进。",
  "Scope owner and client agree the question → analyst checks source readiness → preparation work resolves agreed issues → reviewer checks findings → scope owner discusses the next decision with the client.": "范围负责人与客户就问题达成一致→分析师检查资料准备情况→准备工作解决约定问题→审核员检查发现的问题→范围负责人与客户讨论下一步决策。",
  "Scope owner checks the brief and source files → designer produces a proof → reviewer checks content and output → client approves a specific version → any print order follows the approved version and specifications.": "范围负责人检查概要和源文件 → 设计师制作样稿 → 审核人检查内容和输出 → 客户批准特定版本 → 任何印刷订单都需遵循已批准的版本和规格。",
  "Scope owner narrows the buyer question → researcher gathers dated evidence → language and category review checks interpretation → buyer reviews the options and decides whether to commission a separate test.": "范围负责人缩小买家的问题→研究员收集日期凭证→语言和类别审查以检查解释→买家审查选项并决定是否委托单独测试。",
