  "Total owner work including non-project time: {0}. Counted work hours: {1}. Includes owner work and role delivery only; other roles’ sales/admin time is excluded. These are summed effort, not elapsed turnaround.": "包括非项目时间在内的总负责人工作：{0}。计算的工作小时数：{1}。仅包括负责人工作和角色交付；其他角色的销售/管理时间被排除在外。这些是累计的工作量，而非实际完成的时间。",
  "Total work hours": "总工作小时数",
  "Total work hours sum your time and paid-role time{0}; they do not estimate elapsed turnaround.": "总工作小时数等于您的人工时间和付费角色时间之和{0}；这并不表示模拟完成的耗时。",
  "Total work hours sum your time and paid-role time{0}; they do not estimate elapsed turnaround. All costs include direct costs, allocated overhead and your time allowance. Available per owner hour is before valuing your time, after direct costs and overhead; it is unavailable for zero owner hours. Results exclude tax and unlisted costs. A higher price does not imply a buyer will accept it.": "总工作小时数等于您的时间和付费角色时间{0}；它们不估算模拟完成时间。所有成本包括直接成本、分配的开销和您的时间补贴。按负责人工时计算的可用时间是在评估您的时间、直接成本和开销之后的数值；对于零负责人工时的情况，该数值是不可用的。结果不包括税收和未列出的成本。较高的价格并不意味着买家会接受该价格。",
  "Total:": "总计：",
  "Totals and exclusions can be traced to the supplied source.": "总计和排除项可追溯到提供的来源。",
  "Totals and exclusions can be traced to the supplied source. Missing costs or records remain explicit. The client can distinguish an observed pattern from a causal claim or forecast. The agreed question is answered, or the evidence gap is explained.": "总计和排除项可追溯到提供的来源。缺失的成本或记录仍然明确。客户能够区分观察到的模式与因果声明或预测。约定的问题得到解答，或者证据差距得到解释。",
